content.Text:
Below is a clean TypeScript model set plus a minimal state machine for the Notes → Launchpad flow. No `any`, and state transitions are enforced in types and in a runtime guard.

```ts// Notes → Launchpad workflow stateexport type WorkflowStatus =
 | "draft"
 | "sent_to_launchpad"
 | "building"
 | "complete";

// Core modelsexport interface DesignDocument {
 id: string;
 content: string;
 type: "note" | "spec" | "brief";
 status: WorkflowStatus;
 launchpadProjectId?: string;
}

export interface LaunchpadProject {
 id: string;
 sourceDocId: string;
 buildStatus: "queued" | "running" | "failed" | "succeeded";
 agents: string[];
 progress: number; //0-100 artifacts: Array<{
 id: string;
 type: "file" | "link" | "summary";
 name: string;
 uri: string;
 }>;
}

export interface AgencyTask {
 id: string;
 projectId: string;
 type: "plan" | "build" | "review" | "deliver";
 assignedAgent: string;
 status: "todo" | "in_progress" | "blocked" | "done";
 parentTaskId?: string;
}

// State machineexport type WorkflowEvent =
 | { type: "SEND_TO_LAUNCHPAD" }
 | { type: "START_BUILD" }
 | { type: "MARK_COMPLETE" };

export const workflowTransitions: Record<
 WorkflowStatus,
 Partial<Record<WorkflowEvent["type"], WorkflowStatus>>
> = {
 draft: {
 SEND_TO_LAUNCHPAD: "sent_to_launchpad",
 },
 sent_to_launchpad: {
 START_BUILD: "building",
 },
 building: {
 MARK_COMPLETE: "complete",
 },
 complete: {},
};

export function canTransition(
 from: WorkflowStatus,
 event: WorkflowEvent["type"]
): boolean {
 return Boolean(workflowTransitions[from][event]);
}

export function transition(
 from: WorkflowStatus,
 event: WorkflowEvent["type"]
): WorkflowStatus {
 const next = workflowTransitions[from][event];
 if (!next) {
 throw new Error(`Invalid transition from ${from} on ${event}`);
 }
 return next;
}
```

If you want, I can add tighter compile time guards so invalid transitions are impossible to call in code, or wire this into an existing store pattern in the repo.
